import React from 'react';
import { createRoot } from 'react-dom/client';
import { SubscriptionCenter } from '@/features/vayon/billing/components/SubscriptionCenter';
import { SubscriptionManagement } from '@/features/vayon/billing/components/SubscriptionManagement';
import { WorkspaceTrialBanner } from '@/features/vayon/billing/components/WorkspaceTrialBanner';
import { SubscriptionStatus, InvoiceTable } from '@/features/vayon/billing/components/BillingUI';
import { BillingContactForm } from '@/features/vayon/billing/components/BillingForms';
import { WorkspacePageLayout, WorkspaceHeader } from '@/features/platform/design-system/layout/WorkspaceLayouts';
const params = new URLSearchParams(location.search);
const catalog = ['starter','professional'].flatMap(plan => ['monthly','annual'].map(period => ({ plan, period, productId: 'pro_qa', priceId: `pri_${plan}_${period}`, name: plan, description: 'QA price fixture', amount: period === 'monthly' ? '12345' : '123450', currencyCode: 'USD' })));
const subscription = { id:'qa', planId:'qa-starter', planCode:'starter', planName:'Starter', status:params.has('expired') ? 'trialing' : 'active', trialEndsAt:new Date(Date.now()-1000).toISOString(), currentPeriodEndsAt:'2026-12-01T00:00:00Z', cancelAtPeriodEnd:false, seatQuantity:2, version:1, providerSubscriptionId:'sub_qa' };
const trial = { status:'trialing', endsAt:new Date(Date.now() + (params.has('expired') ? -1000 : 86400000*2)).toISOString(), usage:{properties:1,leads:2,companies:1,members:1} };
window.billingCheckout = [];
let callback;
window.Paddle = { Environment:{set(){}}, Initialize(options){callback=options.eventCallback;}, Update(options){callback=options.eventCallback;}, Checkout:{open(options){window.billingCheckout.push(options);},close(){}}, complete(){callback({name:'checkout.completed'});}, cancel(){callback({name:'checkout.closed'});} };
window.fetch = async (url, options) => { window.billingRequests ??= []; window.billingRequests.push({url,body:JSON.parse(options.body)}); return params.has('failure') ? {ok:false,json:async()=>({success:false})} : {ok:true,json:async()=>({success:true,transactionId:'txn_checkout_qa'})}; };
createRoot(document.getElementById('root')).render(<main id="main-content"><WorkspacePageLayout notice={<WorkspaceTrialBanner snapshot={trial}/>}><WorkspaceHeader title="Subscription Center" description="Manage your plan, workspace usage and billing in one place."/><SubscriptionStatus subscription={subscription}/><SubscriptionCenter catalog={params.has('unconfigured') ? [] : catalog} organizationId="qa-org" workspaceId="qa-workspace" clientToken={params.has('unconfigured') ? undefined : 'test_qa'} environment="sandbox"/><SubscriptionManagement subscription={subscription} catalog={catalog} clientToken="test_qa" environment="sandbox"/><InvoiceTable items={[]}/><BillingContactForm contact={null}/></WorkspacePageLayout></main>);
